/* Question bank. Tuple: [module, question, choices, correctIndex, explanation]. */
window.OSData = window.OSData || {};
window.OSData.quizzes = [
  // ---- Module 1: Fundamentals ----
  [1, "Which CPU mode is allowed to execute privileged instructions such as halting the CPU or modifying page tables?",
    ["User mode", "Kernel mode", "Both modes equally", "Neither; they are emulated in software"], 1,
    "Privileged instructions run only in kernel (supervisor) mode. A user-mode attempt raises a protection fault."],
  [1, "What is the standard mechanism a user program uses to request a service from the kernel?",
    ["A system call (trap)", "A direct function call into kernel memory", "Editing the interrupt vector table", "Writing to a device register"], 0,
    "A system call executes a trap instruction that switches to kernel mode and jumps to a fixed, kernel-controlled entry point."],
  [1, "Why does the OS program a hardware timer to interrupt periodically?",
    ["To measure disk speed", "So the OS can regain control from a process that never yields the CPU", "To keep the clock accurate in user programs", "To flush the TLB"], 1,
    "Without a timer interrupt, a process in an infinite loop could monopolize the CPU. The interrupt hands control back to the kernel."],
  [1, "Which of these is NOT normally a job of the operating system?",
    ["Allocating memory to processes", "Scheduling the CPU", "Compiling source code into machine code", "Providing file abstractions over storage"], 2,
    "Compilers are ordinary user-level programs. The OS manages resources and provides abstractions."],
  [1, "How does a microkernel differ from a monolithic kernel?",
    ["It has no kernel at all", "It keeps only minimal services in the kernel and runs others (file systems, drivers) as user-space servers", "It runs entirely in user mode", "It can only run on single-core CPUs"], 1,
    "Microkernels favor isolation and reliability at the cost of extra message passing; monolithic kernels favor performance."],
  [1, "In a typical system call such as read(), what happens right after the trap instruction executes?",
    ["The process is terminated", "The CPU switches to kernel mode and jumps to the system-call handler", "The kernel copies itself into user space", "Interrupts are permanently disabled"], 1,
    "The trap changes the mode bit and transfers control to the handler selected by the system-call number."],

  // ---- Module 2: Security ----
  [2, "What are the permissions for a file with mode 754?",
    ["Owner rwx, group r-x, others r--", "Owner rwx, group rw-, others r-x", "Owner r-x, group rwx, others r--", "Owner rw-, group r--, others r--"], 0,
    "7 = 4+2+1 = rwx, 5 = 4+1 = r-x, 4 = r--."],
  [2, "Which octal mode corresponds to rw-r--r--?",
    ["600", "644", "664", "755"], 1,
    "rw- = 6, r-- = 4, r-- = 4, so 644."],
  [2, "The principle of least privilege says that…",
    ["Users should have the fewest friends on the system", "Every subject should have only the access rights needed for its task", "All programs should run as administrator", "Only the kernel should have passwords"], 1,
    "Limiting privileges limits the damage from bugs, mistakes and compromised accounts."],
  [2, "In an access-control matrix, an Access Control List (ACL) corresponds to…",
    ["A row (per subject)", "A column (per object)", "The diagonal", "The whole matrix"], 1,
    "An ACL is stored with each object and lists which subjects may do what. A capability list is a row stored per subject."],
  [2, "What does the setuid bit on an executable do?",
    ["Makes the file read-only", "Runs the program with the privileges of the file's owner", "Prevents the file from being deleted", "Encrypts the file"], 1,
    "setuid lets programs like passwd modify protected files, which is powerful and risky if the program is buggy."],
  [2, "Which defense makes memory addresses of the stack, heap and libraries unpredictable to an attacker?",
    ["ACLs", "ASLR (address space layout randomization)", "Round-robin scheduling", "Journaling"], 1,
    "ASLR randomizes layout at load time, making return-oriented exploits harder."],
  [2, "On a Unix directory, what does the execute (x) permission allow?",
    ["Running the directory as a program", "Searching/traversing the directory to reach entries by name", "Listing file names", "Deleting the directory"], 1,
    "x on a directory means “search”. Without it you cannot access entries inside, even if you know their names."],

  // ---- Module 5: Processes ----
  [5, "A running process's time quantum expires. Which state transition happens?",
    ["Running → Waiting", "Running → Ready", "Ready → Running", "Waiting → Ready"], 1,
    "Preemption moves the process back to the ready queue; it is still runnable but not currently on the CPU."],
  [5, "A process waiting for disk I/O finishes its I/O. Where does it go next?",
    ["Running", "Ready", "Terminated", "New"], 1,
    "It becomes ready and must wait for the scheduler to dispatch it again; it does not jump straight to running."],
  [5, "After fork(), what does the call return in the child process?",
    ["The parent's PID", "The child's PID", "0", "-1"], 2,
    "fork() returns 0 in the child, the child's PID in the parent, and -1 on failure."],
  [5, "A program calls fork() three times in a row with no conditionals. How many processes exist at the end (including the original)?",
    ["3", "6", "8", "9"], 2,
    "Each fork doubles the number of processes: 2³ = 8."],
  [5, "What is a zombie process?",
    ["A process stuck in an infinite loop", "A terminated process whose parent has not yet collected its exit status with wait()", "A process with no memory", "A process running as root"], 1,
    "The PCB entry remains so the parent can read the exit status; once wait() is called it is reaped."],
  [5, "Which item is NOT part of a typical Process Control Block (PCB)?",
    ["Saved CPU registers and program counter", "Process state", "Scheduling information", "The complete contents of the process's heap"], 3,
    "The PCB holds metadata and pointers (e.g., page-table base), not the process's memory contents."],
  [5, "Why is a context switch considered overhead?",
    ["It requires a reboot", "The CPU does bookkeeping (saving/restoring state, cache/TLB effects) but no useful user work", "It always takes one second", "It deletes the old process"], 1,
    "Time spent switching doesn't advance any process's computation, so frequent switching lowers throughput."],

  // ---- Module 6: Scheduling ----
  [6, "Which scheduling algorithm gives the minimum average waiting time when all burst times are known in advance?",
    ["FCFS", "Round Robin", "Shortest Job First", "Priority (without aging)"], 2,
    "SJF (and its preemptive form SRTF) is provably optimal for average waiting time."],
  [6, "What is the convoy effect?",
    ["Short processes stuck waiting behind one long CPU-bound process", "Many processes finishing at the same time", "Threads sharing a stack", "Priority inversion"], 0,
    "It is most associated with FCFS: one long job delays everything behind it, lowering CPU/I/O utilization."],
  [6, "Round Robin with an extremely large time quantum behaves like which algorithm?",
    ["SJF", "FCFS", "Priority", "SRTF"], 1,
    "If the quantum exceeds every burst, each process runs to completion in arrival order."],
  [6, "Which technique prevents starvation of low-priority processes?",
    ["Aging (gradually raising priority while waiting)", "Increasing the quantum", "Disabling interrupts", "Using more threads"], 0,
    "Aging guarantees that even a low-priority process will eventually reach the top priority."],
  [6, "P1 (burst 6), P2 (burst 8), P3 (burst 3) all arrive at time 0 and run FCFS in that order. What is the average waiting time?",
    ["4.00", "5.67", "6.67", "9.67"], 2,
    "Waits are 0, 6 and 14, so (0+6+14)/3 = 6.67."],
  [6, "Same three processes (bursts 6, 8, 3, all arriving at 0) under non-preemptive SJF. What is the average waiting time?",
    ["4.00", "6.67", "5.00", "3.00"], 0,
    "Order is P3, P1, P2 with waits 0, 3 and 9, so 12/3 = 4.00."],
  [6, "Turnaround time is defined as…",
    ["Time spent in the ready queue", "Completion time − arrival time", "Time until the first response", "CPU burst length"], 1,
    "Turnaround = waiting + running (+ I/O) time = completion − arrival. Waiting time is turnaround minus burst time."],

  // ---- Module 7: Threads ----
  [7, "Threads of the same process share which of the following?",
    ["Stack", "CPU registers", "Heap and global data", "Program counter"], 2,
    "Threads share code, heap/globals and open files; each has its own stack, registers and program counter."],
  [7, "According to Amdahl's law, what is the maximum speedup with unlimited cores if 50% of a program is parallelizable?",
    ["1.5×", "2×", "4×", "Unlimited"], 1,
    "Speedup ≤ 1/(1−p) = 1/0.5 = 2."],
  [7, "A program is 90% parallelizable. What is Amdahl's speedup on 10 cores?",
    ["1.9×", "5.26×", "9×", "10×"], 1,
    "S = 1 / ((1−p) + p/N) = 1 / (0.1 + 0.09) = 5.26."],
  [7, "Why is a thread context switch usually cheaper than a process context switch?",
    ["Threads never use the CPU", "Threads share an address space, so no page-table switch or TLB flush is needed", "Threads have no registers", "Threads are always user-level"], 1,
    "Within the same process, the memory mapping stays the same, preserving caches and the TLB."],
  [7, "In a many-to-one thread model, what happens when one thread makes a blocking system call?",
    ["Only that thread blocks", "The entire process blocks", "The kernel creates a new thread", "Nothing"], 1,
    "The kernel sees only one schedulable entity, so all user-level threads in the process are blocked."],
  [7, "A scheduler uses a 10 ms quantum and each context switch costs 1 ms. What fraction of time is spent on useful work?",
    ["≈ 90.9%", "90%", "≈ 99%", "50%"], 0,
    "Efficiency = q / (q + s) = 10/11 ≈ 90.9%."],

  // ---- Module 9: Synchronization ----
  [9, "What is a race condition?",
    ["Two processes competing for CPU time", "A bug where the result depends on the unpredictable interleaving of concurrent operations on shared data", "A thread running faster than expected", "A deadlock between two threads"], 1,
    "e.g., two threads doing counter++ can lose updates because load, add and store are not atomic."],
  [9, "Which is NOT one of the three requirements for a critical-section solution?",
    ["Mutual exclusion", "Progress", "Bounded waiting", "Maximum throughput"], 3,
    "The classic requirements are mutual exclusion, progress and bounded waiting."],
  [9, "A thread calls wait() (P) on a counting semaphore whose value is 0. What happens?",
    ["The semaphore becomes negative and the thread continues", "The thread blocks until another thread signals (V)", "The program crashes", "The semaphore resets to 1"], 1,
    "wait() decrements if positive; otherwise the caller is blocked until a signal arrives."],
  [9, "In the bounded-buffer producer/consumer problem with buffer size N, what are the initial semaphore values?",
    ["empty = 0, full = N, mutex = 0", "empty = N, full = 0, mutex = 1", "empty = 1, full = 1, mutex = 1", "empty = N, full = N, mutex = N"], 1,
    "empty counts free slots (N), full counts filled slots (0), and mutex protects the buffer (1)."],
  [9, "What is priority inversion?",
    ["A high-priority task is delayed because a low-priority task holds a lock it needs and is itself preempted by medium-priority work", "Priorities are sorted in reverse", "A thread's priority is set to zero", "Two tasks swap priorities"], 0,
    "Priority inheritance (temporarily boosting the lock holder) is the standard fix; it famously affected the Mars Pathfinder."],
  [9, "When are spinlocks a reasonable choice?",
    ["For very long waits on a single-CPU system", "For short critical sections on multiprocessors", "Never", "Only for disk I/O"], 1,
    "Spinning avoids a context switch, which is cheaper than sleeping when the lock will be released very soon."],

  // ---- Module 11: Deadlocks ----
  [11, "Which of these is NOT one of the four necessary conditions for deadlock?",
    ["Mutual exclusion", "Hold and wait", "Starvation", "Circular wait"], 2,
    "The Coffman conditions: mutual exclusion, hold and wait, no preemption, circular wait."],
  [11, "Imposing a global ordering on resources and requiring requests in that order prevents which condition?",
    ["Mutual exclusion", "Hold and wait", "No preemption", "Circular wait"], 3,
    "If everyone acquires resources in increasing order, a cycle cannot form."],
  [11, "What does it mean for a system state to be “safe”?",
    ["No process is waiting", "There exists some order in which all processes can finish, even with their maximum demands", "All resources are free", "Deadlock has already occurred"], 1,
    "A safe state guarantees no deadlock. An unsafe state does not guarantee deadlock, but it is risky."],
  [11, "The Banker's algorithm is an example of…",
    ["Deadlock prevention", "Deadlock avoidance", "Deadlock detection", "Ignoring deadlock"], 1,
    "It grants a request only if the resulting state remains safe. This requires knowing each process's maximum claim in advance."],
  [11, "In the dining philosophers problem, what can happen if every philosopher picks up their left fork at the same time?",
    ["Everyone eats", "Deadlock (circular wait)", "Starvation of a single philosopher only", "A race on the table"], 1,
    "Each holds one fork and waits forever for the right fork, held by a neighbor."],
  [11, "A resource-allocation graph has a cycle and every resource type has exactly one instance. What can you conclude?",
    ["Deadlock exists", "The system is safe", "No deadlock is possible", "Nothing"], 0,
    "With single-instance resources, a cycle is both necessary and sufficient for deadlock."],
  [11, "What is the “ostrich algorithm”?",
    ["Aggressively killing processes", "Ignoring the deadlock problem because it is rare and prevention is costly", "A deadlock-detection algorithm", "A scheduling algorithm"], 1,
    "Many general-purpose OSes effectively do this and leave deadlock handling to the application."],

  // ---- Module 13: Memory management ----
  [13, "What is external fragmentation?",
    ["Wasted space inside an allocated block", "Enough total free memory exists, but it is split into non-contiguous holes that are each too small", "Memory used by the kernel", "Swap space that is full"], 1,
    "It affects contiguous allocation; compaction or paging can address it."],
  [13, "Which kind of fragmentation does paging eliminate?",
    ["Internal", "External", "Both", "Neither"], 1,
    "Paging allocates fixed-size frames, so any free frame fits any page. It still has internal fragmentation in the last page."],
  [13, "A 32-bit logical address space uses 4 KB pages. How many bits form the page number?",
    ["10", "12", "20", "22"], 2,
    "4 KB = 2¹² bytes, so 12 offset bits and 32 − 12 = 20 page-number bits."],
  [13, "Page size is 1024 bytes. Logical address 5000 is in which page, at what offset?",
    ["Page 4, offset 904", "Page 5, offset 0", "Page 4, offset 1000", "Page 3, offset 928"], 0,
    "5000 ÷ 1024 = 4 remainder 904."],
  [13, "A process needs 72,766 bytes and the page size is 2,048 bytes. How much internal fragmentation results?",
    ["0 bytes", "962 bytes", "1,086 bytes", "2,048 bytes"], 1,
    "It needs 36 pages = 73,728 bytes. 73,728 − 72,766 = 962 bytes wasted in the last page."],
  [13, "What is the job of the Memory Management Unit (MMU)?",
    ["Schedule processes", "Translate logical addresses to physical addresses at run time", "Store files", "Manage network packets"], 1,
    "The MMU uses page tables (with a TLB cache) to translate every memory reference in hardware."],
  [13, "Which placement strategy is generally fastest because it stops at the first adequate hole?",
    ["Best-fit", "Worst-fit", "First-fit", "Random-fit"], 2,
    "First-fit avoids scanning the entire list; best-fit and worst-fit must search all holes unless sorted."],

  [13, "A 32-bit system uses 4 KiB pages and 4-byte page-table entries. How big is a single flat page table for one process?",
    ["4 KiB", "64 KiB", "4 MiB", "4 GiB"], 2,
    "There are 2^32 / 2^12 = 2^20 pages, so 2^20 entries × 4 bytes = 4 MiB, even for a process that uses only a few pages."],
  [13, "With the 10 + 10 + 12 two-level layout, what are the top-level and second-level indices of virtual address 0x00403004?",
    ["(1, 3)", "(3, 1)", "(4, 3)", "(0, 4)"], 0,
    "0x00403004 >> 22 = 1 selects the top-level entry. (0x00403004 >> 12) & 0x3FF = 0x403 & 0x3FF = 3 selects the second-level entry. The offset is 4."],
  [13, "Why does a multi-level page table use much less memory than a flat one for a typical process?",
    ["It compresses the entries", "Second-level tables are only created for the regions of the address space that are actually used", "It stores page tables on disk", "It uses smaller pages"], 1,
    "Large gaps in the address space need no lower-level tables at all; their top-level entries are simply marked not present."],
  [13, "A two-level system has no page-walk cache. How many memory references does an access need on a TLB miss (the page is mapped)?",
    ["1", "2", "3", "4"], 2,
    "Two page-table reads (one per level) plus the data access itself: 3 references."],
  [13, "x86-64 uses 4 KiB pages with 8-byte entries and four table levels for 48-bit addresses. How many index bits does each level use?",
    ["8", "9", "10", "12"], 1,
    "A table is one 4 KiB page holding 4096 / 8 = 512 entries, so it needs 9 bits. 4 × 9 + 12 offset bits = 48."],
  [13, "What problem do ASIDs (address-space identifiers) in the TLB solve?",
    ["They make pages bigger", "They avoid flushing the whole TLB on every context switch, because each entry is tagged with its process", "They remove the need for page tables", "They encrypt translations"], 1,
    "Without tags, entries from the previous process would be wrong, so the TLB must be flushed on each switch and the next process starts cold."],
  [13, "Why can huge pages (for example 2 MiB) improve performance?",
    ["They reduce internal fragmentation", "One TLB entry covers much more memory, so the TLB reach grows and the page walk is shorter", "They need no page table", "They are always faster to allocate"], 1,
    "A 2 MiB page skips the last table level and one TLB entry maps 512 times more memory. The trade-off is more internal fragmentation and the need for contiguous frames."],
  [13, "The TLB hit ratio is 98%, a TLB lookup takes 1 ns, memory takes 100 ns, and the page table has 4 levels. What is the effective access time (approximately)?",
    ["101 ns", "105 ns", "109 ns", "501 ns"], 2,
    "EAT = 0.98 × (1 + 100) + 0.02 × (1 + 4 × 100 + 100) = 98.98 + 10.02 = 109 ns."],

  // ---- Module 14: Virtual memory ----
  [14, "When does a page fault occur?",
    ["A process writes to a file", "A referenced page is not currently mapped to a physical frame", "The disk is full", "A thread exits"], 1,
    "The OS handles the trap by loading the page from backing store (or raising a segmentation fault if the access is illegal)."],
  [14, "Belady's anomaly is the surprising effect that, with certain algorithms such as FIFO…",
    ["Fewer frames produce fewer faults", "More frames can produce more page faults", "Page faults vanish", "The TLB gets slower"], 1,
    "FIFO is not a stack algorithm; LRU and OPT are immune to Belady's anomaly."],
  [14, "Why can't the optimal (OPT/MIN) page-replacement algorithm be implemented in a real OS?",
    ["It is too slow in hardware", "It needs knowledge of future references", "It uses too much memory", "It only works on SSDs"], 1,
    "OPT replaces the page whose next use is farthest in the future; it serves as a benchmark."],
  [14, "Memory access takes 100 ns, a page fault costs 8 ms, and the fault rate is 0.001. What is the effective access time (≈)?",
    ["≈ 100 ns", "≈ 800 ns", "≈ 8,100 ns", "≈ 80,000 ns"], 2,
    "EAT = 0.999 × 100 + 0.001 × 8,000,000 ≈ 8,100 ns, an 81× slowdown from just 0.1% faults."],
  [14, "What is thrashing?",
    ["A CPU overheating", "A process spending more time paging than executing because it lacks enough frames", "Excessive context switching between threads", "A disk head crash"], 1,
    "It is remedied by providing enough frames (working set) or reducing the degree of multiprogramming."],
  [14, "Reference string 1, 2, 3, 1, 4 with 3 frames and LRU: how many page faults occur?",
    ["3", "4", "5", "2"], 1,
    "Faults on 1, 2, 3 (cold), a hit on 1, then 4 faults and evicts 2, the least recently used. That makes 4 faults."],

  // ---- Module 15: Disk & I/O ----
  [15, "What does seek time measure on a hard disk?",
    ["Time for the platter to rotate to the sector", "Time to move the read/write head to the correct cylinder", "Time to transfer the data", "Time to boot"], 1,
    "Total access time = seek + rotational latency + transfer time. Seek usually dominates."],
  [15, "What is the main drawback of SSTF (Shortest Seek Time First) disk scheduling?",
    ["It has high total head movement", "It can starve requests far from the head", "It only works on SSDs", "It requires future knowledge"], 1,
    "A stream of nearby requests can postpone distant ones indefinitely."],
  [15, "Which algorithm is nicknamed the “elevator algorithm”?",
    ["FCFS", "SSTF", "SCAN", "Random"], 2,
    "The head sweeps in one direction servicing requests, then reverses, like an elevator."],
  [15, "What is the advantage of C-SCAN over SCAN?",
    ["Less total movement always", "More uniform wait times, since requests are serviced in one direction only", "No seeks", "Works without a queue"], 1,
    "After reaching the end, the head returns to the start without servicing, treating cylinders as a circular list."],
  [15, "Head starts at cylinder 53. Requests: 98, 183, 37, 122, 14, 124, 65, 67. What is the total head movement under FCFS?",
    ["236", "640", "208", "559"], 1,
    "45 + 85 + 146 + 85 + 108 + 110 + 59 + 2 = 640 cylinders. (SSTF achieves 236.)"],
  [15, "What is the purpose of DMA (Direct Memory Access)?",
    ["To let devices transfer data to/from memory without the CPU handling each byte", "To encrypt disk contents", "To schedule the disk", "To speed up the CPU clock"], 0,
    "The CPU sets up the transfer; the DMA controller interrupts it only when finished."],
  [15, "Why is disk-arm scheduling mostly irrelevant for SSDs?",
    ["SSDs are always faster than RAM", "SSDs have no moving heads, so there is no seek time", "SSDs do not have queues", "SSDs ignore I/O requests"], 1,
    "SSD schedulers focus instead on parallelism, wear leveling and write amplification."],

  // ---- Module 16: File systems ----
  [16, "What is a main weakness of contiguous file allocation?",
    ["Slow sequential reads", "External fragmentation and difficulty growing files", "Large metadata", "No random access"], 1,
    "Contiguous allocation has excellent read performance but needs a large enough free extent, and files cannot easily grow."],
  [16, "Why is linked allocation poor for random access?",
    ["Blocks are too small", "To reach block k you must follow k pointers from the beginning", "It needs contiguous space", "It cannot store large files"], 1,
    "FAT improves this by keeping the pointers in an in-memory table instead of in each data block."],
  [16, "What does an inode typically NOT contain?",
    ["File size and timestamps", "Permissions and owner", "Pointers to data blocks", "The file's name"], 3,
    "Names live in directory entries, which map names to inode numbers. That is why hard links can give one file several names."],
  [16, "A file system uses 4 KiB blocks, 4-byte block pointers, and inodes with 12 direct pointers plus 1 single-indirect pointer. What is the maximum file size?",
    ["48 KiB", "4,096 KiB", "4,144 KiB", "4 GiB"], 2,
    "An indirect block holds 4096/4 = 1024 pointers, so (12 + 1024) × 4 KiB = 4,144 KiB."],
  [16, "What is the difference between a hard link and a symbolic link?",
    ["There is none", "A hard link is another directory entry for the same inode; a symlink is a small file holding a path", "Hard links can only point to directories", "Symbolic links share inodes"], 1,
    "Deleting the original name leaves a hard-linked file intact; a symlink would dangle."],
  [16, "What problem does file-system journaling solve?",
    ["Slow disks", "Inconsistent metadata after a crash or power loss", "Fragmentation", "File encryption"], 1,
    "Changes are first written to a log, so recovery can replay or discard incomplete operations quickly instead of scanning everything."],

  // ---- Module 18: The OS landscape ----
  [18, "Why must a mobile app be ready to save its state whenever it moves to the background?",
    ["Mobile CPUs cannot run two programs at once", "The OS may terminate background apps to reclaim memory or battery, without warning", "Apps are not allowed to use files", "The kernel deletes the app's code when it is paused"], 1,
    "Android and iOS control the app lifecycle. Under memory pressure they end background processes (Android's low-memory killer, iOS's jetsam) rather than paging to flash storage."],
  [18, "How does Qubes OS limit the damage from a compromised application?",
    ["It encrypts every file with a different password", "It runs activities in separate virtual machines on the Xen hypervisor, so a compromise stays inside one compartment", "It disables the network", "It only allows signed applications"], 1,
    "Qubes assumes some software will be compromised and uses compartmentalization: work, personal and untrusted activities live in different VMs."],
  [18, "What is the defining promise of a real-time operating system?",
    ["The highest average speed", "Meeting deadlines predictably", "Support for the most applications", "Automatic memory compaction"], 1,
    "Real-time means timing guarantees. A slow but predictable system can be real-time; a fast but unpredictable one cannot."],
  [18, "Which two operating systems share the same Darwin/XNU kernel core?",
    ["macOS and iOS", "Android and iOS", "Windows and macOS", "ChromeOS and macOS"], 0,
    "Apple's platforms all build on Darwin. Android and ChromeOS, by contrast, are both built on the Linux kernel."],
  [18, "From which family does z/VSE descend, compared with z/OS?",
    ["Both descend from OS/360", "z/VSE descends from DOS/360; z/OS descends from OS/360 and MVS", "z/VSE descends from Unix", "z/VSE descends from System/38"], 1,
    "IBM's mainframe line has two separate families: OS/360 → MVS → z/OS, and DOS/360 → DOS/VSE → z/VSE."],
  [18, "What does “single-level storage” on IBM i mean?",
    ["Only one user can log in", "Main memory and disk are treated as one very large address space", "Files cannot have directories", "The database is stored on a single disk"], 1,
    "Objects live in one address space and the system moves them between memory and disk, so applications do not do explicit paging or file I/O the way they would on a PC."],
  [18, "What is the purpose of the channel subsystem on a mainframe?",
    ["To encrypt network traffic", "To handle I/O operations so the CPUs can keep computing", "To schedule batch jobs", "To store the system catalog"], 1,
    "It is a dedicated I/O processing layer, a more powerful relative of DMA, which helps mainframes sustain very high I/O throughput."],
  [18, "Why do small RTOSes such as FreeRTOS usually avoid virtual memory?",
    ["Virtual memory is illegal on microcontrollers", "Page faults make timing unpredictable, and many microcontrollers have no MMU", "They only run one instruction", "They store all code on disk"], 1,
    "Demand paging introduces delays that are hard to bound, and tiny chips often lack the hardware, so these systems use simple, predictable memory models."],
  [18, "In a microkernel RTOS such as QNX, what happens if a device driver crashes?",
    ["The whole kernel crashes", "Only that driver process fails and it can be restarted", "The OS is reinstalled", "All user programs are deleted"], 1,
    "Drivers run as separate user-space processes, so a fault is contained and recoverable, which is one practical benefit of the microkernel design."],
  [12,"Why do two processes need a special mechanism to exchange data?",["The CPU cannot copy memory","Each process has its own protected address space, so one cannot simply read another's variables","Files can only be opened by one process","Processes run on different machines"],1,"Isolation is the point of a process. Pipes, sockets, queues and shared memory are the controlled holes the kernel provides through that isolation."],
  [12,"A writer writes 3 bytes, then 4 bytes, into an ordinary pipe. The reader asks for 100 bytes. What does it get?",["Only the first 3 bytes, because that was the first write","All 7 bytes in one read: a pipe is a byte stream with no message boundaries","An error, because the sizes differ","Nothing until the writer closes the pipe"],1,"A pipe delivers bytes, not messages. A message queue (or a datagram socket) is what preserves the boundaries."],
  [12,"A reader calls read() on an empty pipe whose write end is still open somewhere. What happens?",["It returns 0 immediately","It returns an error","It sleeps until data arrives or every write end is closed","The kernel creates a zero byte"],2,"Blocking is the normal behavior. Returning 0 would mean end of file, which is only reported once no process holds a write end any more."],
  [12,"Why must the child in a pipe example close the write end it inherited from fork()?",["Pipes only allow one open end","Otherwise the child itself keeps a write end open, so its own read never sees end of file","The kernel would run out of file descriptors","Closing is required for the data to be copied"],1,"End of file means every write end is closed. A forgotten copy of the write end is a classic cause of a program that hangs forever."],
  [12,"What happens when a process writes to a pipe that has no remaining reader?",["The data is stored until a reader appears","The write blocks forever","The writer gets SIGPIPE (or an EPIPE error): a broken pipe","The data is silently discarded with success"],2,"Nobody could ever read the data, so the kernel reports an error instead of letting the writer fill a buffer or wait for nothing."],
  [12,"After fork(), a child sets an ordinary variable and a MAP_SHARED mapping to new values. What does the parent see?",["Both new values","Neither new value","The old ordinary value and the new value in the shared mapping","The new ordinary value only"],2,"fork gives the child its own copy of ordinary memory (copy-on-write). A shared mapping refers to the same physical pages in both processes."],
  [12,"What is the main trade-off of shared memory compared with a pipe?",["It is slower because of extra copies","It needs no kernel at all","It avoids per-transfer system calls and copies, but the processes must synchronize access themselves","It only works between a parent and its child"],2,"The kernel no longer orders the operations, so two writers can race exactly as in Module 9. Pair it with a mutex or semaphore."],
  [12,"Which mechanism lets two unrelated processes on different computers communicate?",["An anonymous pipe","Shared memory","A signal","A network socket"],3,"Pipes, shared memory and queues are local to one machine. Sockets use the same read and write idea over a network."],
  [12,"Which statement about signals is true?",["They carry large amounts of data","They are small asynchronous notifications such as SIGINT or SIGTERM","They require both processes to be parent and child","They are the fastest way to transfer files"],1,"A signal says that something happened. It carries a number but no payload, so use another mechanism to move data."],
  [19,"What is the key difference between a container and a virtual machine?",["Containers cannot run Linux programs","A container shares the host's kernel, while a VM runs its own kernel on virtual hardware","Containers always run slower","A VM is a process and a container is not"],1,"A container is an ordinary process with a restricted view. Every container on a host runs on the same kernel; each VM boots a separate one."],
  [19,"What does a Linux namespace do?",["It limits how much CPU a process can use","It gives a process a private view of one kind of resource, such as process IDs or the network","It encrypts a process's memory","It lets a process run as another computer"],1,"Namespaces control what a process can see. Control groups control how much it can use."],
  [19,"What does a control group (cgroup) do?",["It hides files from a process","It limits and accounts for the CPU, memory and I/O used by a group of processes","It gives the group a new kernel","It assigns IP addresses"],1,"Control groups are the resource-limit half of a container. Without them a container could use all of the host's memory."],
  [19,"A container reaches its memory limit and cannot free any. What does the kernel do?",["Reboots the host","Kills a process inside that container","Kills the process using the most memory on the whole host","Adds more RAM"],1,"The out-of-memory kill is applied within the group, so a runaway container does not take down its neighbors."],
  [19,"Why is the first process inside a new PID namespace numbered 1?",["It is the oldest process on the host","Each PID namespace has its own numbering, and its first process acts as that namespace's init","The host assigns it that number for security","All processes start at 1"],1,"The same process has a different number on the host. If the namespace's init exits, the kernel ends the other processes in it."],
  [19,"Which statement about a type 1 hypervisor is correct?",["It runs as an ordinary program on a desktop OS","It runs directly on the hardware and hosts guest operating systems","It cannot run more than one guest","It is a kind of container runtime"],1,"Type 2 hypervisors such as desktop virtualization programs sit on a host OS; type 1 hypervisors are the lowest software layer."],
  [19,"What is a VM exit?",["A guest operating system shutting down","The CPU stopping the guest and switching to the hypervisor because the guest did something only the hypervisor may do","Deleting a virtual machine","A container stopping"],1,"Each exit costs thousands of cycles, which is why virtual devices such as virtio batch their requests."],
  [19,"Why can a Windows application not run unchanged in a Linux container on a Linux host?",["Containers block all Windows files","The container uses the host's Linux kernel, whose system calls differ from Windows'","Containers do not support applications","Linux containers cannot access memory"],1,"The kernel is not virtualized. A VM could run Windows on a Linux host because it brings its own Windows kernel."],
  [19,"Why do cloud providers often run each customer's containers inside a separate VM?",["Containers cannot run on bare metal","A kernel bug or escape in a shared kernel would expose every neighbor, and a VM boundary is much harder to cross","VMs are free","Containers need a hypervisor to start"],1,"Containers on one kernel share its attack surface. A hypervisor's interface is far smaller, so it is a stronger wall between mutually untrusting tenants."],
  [10,"What does pthread_cond_wait do with the mutex it is given?",["Nothing; the caller must unlock it first","It atomically releases the mutex and puts the thread to sleep, and reacquires the mutex before returning","It locks the mutex permanently","It destroys the mutex"],1,"Doing release-and-sleep as one step is what prevents a lost wake-up between checking the condition and sleeping."],
  [10,"Why should a condition-variable wait be inside a while loop rather than an if?",["Loops are faster","With Mesa semantics, another thread can change the state between the signal and the waiter running, and wake-ups can be spurious, so the condition must be re-checked","The compiler requires it","A while loop acquires the lock"],1,"A signal is a hint that the condition may be true. The loop turns the hint into a guarantee."],
  [10,"What does signaling a condition variable do under Mesa semantics?",["Immediately transfers the lock to the waiter","Makes one waiter ready; it runs later, after it reacquires the lock","Kills the signaling thread","Releases all locks"],1,"The signaler keeps running (and holding the lock). That is the very reason the woken thread must re-check."],
  [10,"What is a monitor?",["A tool that displays CPU use","Shared data bundled with the lock and condition variables that protect it, so one thread at a time is active inside","A kind of interrupt","A hardware timer"],1,"Monitors move the locking discipline out of every caller and into the data structure, which is much harder to misuse than raw semaphores."],
  [10,"In the readers–writers problem, which accesses may overlap?",["Any two accesses","Only a reader and a writer","Any number of readers, but a writer must be alone","Only two writers"],2,"Reads do not interfere with one another, so they can share. A write changes the data and needs exclusive access."],
  [10,"Under reader preference, what can happen to a writer?",["It always goes first","It can starve if readers keep arriving so that the lock is never free","It becomes a reader","It is killed"],1,"Readers never wait behind other readers, so a continuous stream of overlapping readers keeps the writer out indefinitely."],
  [10,"Under writer preference, what can happen to a reader?",["It can starve if writers keep arriving","It can write instead","It always runs first","Nothing; readers are never delayed"],0,"The mirror image: new readers are held back whenever a writer is waiting, so a stream of writers can keep readers out."],
  [10,"What does a first-come, first-served read-write lock guarantee?",["Maximum parallelism","Nobody overtakes: a request waits only for the ones that arrived before it, so no one starves","Readers always go first","Writers never wait"],1,"Fairness costs some parallelism, because a reader behind a waiting writer cannot slip in beside the current readers."],
  [10,"When is a read-write lock worth its extra complexity over a plain mutex?",["Always","When reads vastly outnumber writes and each read holds the lock long enough that sharing helps","When there is only one thread","When writes are the most common operation"],1,"A read-write lock is more expensive to acquire. With short critical sections or frequent writes, a simple mutex can be faster."],
  [4,"Why does the BIOS read only the first sector of the boot disk?",["It cannot read more than 512 bytes ever","It does not understand file systems, so it loads one fixed location and lets that code find the rest","Sectors after the first are encrypted","The first sector holds the whole kernel"],1,"The BIOS knows only how to read sectors by number. The boot code in sector 0 is tiny and exists to load a bigger loader that does understand file systems."],
  [4,"What are the last two bytes of a valid MBR?",["0x00 0x00","0xFF 0xFF","0x55 0xAA","0xAA 0x55"],2,"The signature 0x55 0xAA (bytes 510 and 511) tells the BIOS the sector looks like a boot sector. Without it the BIOS skips the disk."],
  [4,"How many partitions can an MBR describe, and where is the table?",["Unlimited, in a separate file","Four 16-byte entries starting at byte 446","Eight entries at byte 0","One entry at byte 510"],1,"The MBR has room for exactly four primary entries. Larger layouts use an extended partition, or GPT, which allows many more."],
  [4,"Why is a multi-byte value such as a partition's start sector stored least-significant byte first?",["It is encrypted that way","x86 processors are little-endian, and the format was designed around them","It saves disk space","It is a random choice made at format time"],1,"Little-endian ordering is the native byte order of x86, so the BIOS-era structures use it. A program reading the bytes must reassemble them in that order."],
  [4,"What is the job of the initramfs?",["To be the permanent root file system","To hold the drivers and tools needed to find and mount the real root file system","To store user files","To replace the kernel"],1,"The kernel cannot use a disk without a driver, and the driver may live on that disk. A small file system loaded into RAM breaks the loop."],
  [4,"What does the kernel start once the root file system is mounted?",["The BIOS","The init process (PID 1), which starts all the other services","The boot loader again","The firmware"],1,"PID 1 is the first user-space process. If the kernel cannot start it, there is nothing for the machine to run and it panics."],
  [4,"What does Secure Boot do when the boot loader has been modified?",["Runs it anyway but shows a warning","Refuses to run it because its signature no longer verifies","Deletes it","Boots from the network instead"],1,"Each stage verifies the signature of the next before running it, so changed code is refused. That is why malware that replaces a boot loader is blocked."],
  [4,"In a chain of trust, what happens to components after the first tampered link?",["They are still trusted if their own files are unchanged","They are not trusted, because nothing verified them from a trusted starting point","They are repaired","They run in a sandbox automatically"],1,"Trust flows from the root, link by link. Once a link fails, everything it would have vouched for is no longer vouched for."],
  [4,"Two services are not connected by any dependency. How does an init system such as systemd start them?",["One after the other in alphabetical order","At the same time, because neither waits for the other","Never, until the user requests it","Only after all other services are finished"],1,"Starting independent services together is a large part of why parallel boot is faster. The critical path of dependencies sets the minimum total time."],
  [8,"How does a multilevel feedback queue treat a job that blocks for I/O before its time slice ends?",["It drops a level","It keeps its level, so interactive jobs stay at high priority","It is killed","It moves to the lowest queue"],1,"Using the whole slice is taken as a sign of a CPU-bound job. Giving up the CPU early is a sign of an interactive one, which the scheduler rewards."],
  [8,"Why does a multilevel feedback queue need a periodic priority boost?",["To save energy","So that a job stuck in the lowest queue cannot starve, and a job that has become interactive is noticed","To increase the time slice","To avoid context switches"],1,"Without it, a steady stream of short jobs at the top can keep the bottom queues waiting indefinitely."],
  [8,"What makes a system “hard real-time”?",["It is very fast","Missing a deadline is a failure of the system, not just a slowdown","It has many CPUs","It runs only one task"],1,"Real-time means timing is part of correctness. A flight controller that responds late is wrong, however fast it is on average."],
  [8,"Rate-monotonic scheduling assigns the highest priority to which task?",["The one with the longest execution time","The one with the shortest period","The one released most recently","The one with the nearest deadline"],1,"Rate-monotonic gives fixed priorities by period: the more often a task must run, the higher its priority."],
  [8,"Which statement about earliest-deadline-first (EDF) for periodic tasks with deadline equal to period is correct?",["It never preempts","All deadlines are met if and only if total CPU utilization is at most 100%","It needs fixed priorities","It is always worse than rate-monotonic"],1,"EDF is optimal on one CPU: if any algorithm can meet all deadlines, EDF can. Utilization at or below 1 is the exact test."],
  [8,"Two tasks have utilization 0.97 in total. What can be said?",["Rate-monotonic is guaranteed to work","EDF can schedule them, but rate-monotonic may miss a deadline","Neither can ever work","Both are guaranteed to work"],1,"The rate-monotonic guarantee for two tasks stops at about 83%. Between that and 100% it depends on the tasks, and EDF is still fine."],
  [8,"What is the cost of moving a task to a different CPU?",["None","Its data is no longer in that CPU's cache, so it runs slower until the cache warms up","The task restarts from the beginning","The task loses its priority"],1,"Caches are per core. Schedulers therefore try to keep a task where it ran last (affinity) and move it only when the imbalance is worth it."],
  [8,"In work stealing, who initiates a move?",["The busy CPU pushes work away","An idle CPU takes a waiting task from a busy CPU's queue","The user","The disk"],1,"The idle CPU is the one that knows it has spare capacity, so letting it pull work spreads the balancing cost over the cores that are not busy."],
  [8,"Why can pinning a process to one CPU with CPU affinity be useful?",["It always makes the program faster","It keeps the cache warm and avoids migrations, which helps latency-sensitive or cache-heavy work, at the cost of flexibility","It gives the process more memory","It disables preemption"],1,"Pinning trades the scheduler's freedom for predictability. It can backfire if the pinned CPU is busy while others idle."],
  [18,"What is distinctive about the way Plan 9 gives each process its resources?",["Every process shares one global file tree","Every process builds its own private namespace of what it can see","Processes cannot use files at all","Resources are given out by an administrator only"],1,"Plan 9 treats resources as files and lets each process assemble its own view of them. Linux namespaces, the basis of containers, grew from the same idea."],
  [18,"Why does a microkernel such as MINIX 3 or QNX contain a failing device driver better than a monolithic kernel?",["Drivers are written more carefully","The driver runs as an ordinary user-space process, so it can be restarted without taking down the kernel","Microkernels have no drivers","The hardware prevents drivers from failing"],1,"In a monolithic kernel a driver bug runs with full privilege and can corrupt anything. In a microkernel the driver is just a restricted process."],
  [18,"What was z/TPF designed to do especially well?",["Run desktop applications","Handle enormous numbers of very short transactions with predictable response times","Run scientific simulations","Host virtual machines"],1,"It grew from airline reservations. Its design gives up general-purpose flexibility so that each short transaction is fast and its timing predictable."],
  [18,"What does OpenBSD's pledge do?",["Encrypts the disk","Lets a program promise which kinds of system calls it will use, and the kernel enforces the promise","Sets a user's password","Schedules a process earlier"],1,"It is least privilege applied by the program to itself: after the pledge, a hijacked program cannot do the things it promised not to."],
  [3,"Why is a function that copies input into a fixed-size buffer without checking the length dangerous?",["It is always slow","Extra input can overwrite nearby memory on the stack, including the return address","It uses too much memory","It cannot read text"],1,"Anything the caller supplies beyond the buffer's size spills into the saved state above it. Overwriting the return address lets an attacker choose where the function goes next."],
  [3,"What does a stack canary protect against?",["Running out of memory","An overflow reaching the return address undetected: the changed canary is noticed before the function returns","Slow programs","Wrong passwords"],1,"The canary sits between the buffer and the return address. An overflow must pass through it, and the function checks it before returning."],
  [3,"Non-executable memory (NX) stops which attack?",["Running code that the attacker injected into the stack","Every buffer overflow","Password guessing","Network sniffing"],0,"NX forbids running data as code. It does not stop an attacker from reusing code that already exists, which is why it is used together with other defenses."],
  [3,"What does ASLR make harder for an attacker?",["Reading the source code","Knowing where code and data are in memory, so jumping to a chosen address is a guess","Logging in","Sending packets"],1,"With randomized addresses, a wrong guess usually crashes the program instead of taking it over, unless the attacker has an information leak."],
  [3,"Why are stack canaries, NX and ASLR used together rather than one alone?",["Each defense is slow","Each one can be bypassed in a way the others cover: this is defense in depth","They share a single secret","The law requires it"],1,"A leak defeats the canary and ASLR; reusing existing code defeats NX. Together they raise the cost of an attack a great deal."],
  [3,"Two users choose the same password and the system stores plain, unsalted hashes. What does an attacker who steals the file learn?",["Nothing","That they share a password, and cracking one hash cracks both","Their usernames only","Their last login"],1,"Identical inputs give identical hashes. A random salt per user makes the stored values differ."],
  [3,"What does a salt do to stored password hashes?",["It makes hashing faster","It makes each user's hash unique, so precomputed tables of common password hashes do not work","It encrypts the file","It shortens the password"],1,"The salt is stored with the hash and is not secret. Its job is to force the attacker to work on each account separately."],
  [3,"Why should a password hash be deliberately slow?",["To annoy users","Every guess costs an attacker the same extra work, so the number of guesses per second falls","Slow hashes are more random","To save disk space"],1,"A login runs the hash once, so a small delay is acceptable. An attacker trying billions of guesses pays it billions of times."],
  [3,"In STRIDE, a user who denies having done something, with no record to prove otherwise, is an example of which threat?",["Spoofing","Repudiation","Tampering","Denial of service"],1,"Repudiation is about accountability. Audit logs that tie actions to identities are the usual defense."],
  [17,"A RAID 5 array has four 4 TB disks. How much data can it hold, and how many disk failures can it always survive?",["16 TB and 2","12 TB and 1","8 TB and 2","12 TB and 0"],1,"One disk's worth of space holds parity: (4 − 1) × 4 = 12 TB. Any single disk can fail and be rebuilt; a second failure loses the array."],
  [17,"How does RAID 5 rebuild the data of a failed disk?",["It reads a backup","It XORs the surviving disks, including the parity disk","It asks the user","It copies the mirror disk"],1,"Parity is the XOR of the data blocks, so XOR-ing everything that survived gives the missing block."],
  [17,"Why can RAID 5 not survive two failed disks?",["The controller overheats","Parity is one equation, and two missing disks are two unknowns","Parity is only stored on one disk","RAID 5 forbids a second spare"],1,"With one parity block per stripe there is only enough information to recover a single missing block. RAID 6 stores a second, different parity."],
  [17,"Why is rebuilding a large RAID 5 array especially risky?",["The rebuild erases the parity","Every surviving disk must be read completely, and one unreadable sector then loses data","The spare disk is always slower","The array cannot be used during rebuild"],1,"Reading tens of terabytes makes an unrecoverable read error likely, and with no redundancy left there is nothing to correct it."],
  [17,"Which statement about RAID and backups is true?",["RAID makes backups unnecessary","RAID protects against a disk failing but not against deletion, corruption or disasters","RAID is a kind of backup","Backups are only for SSDs"],1,"RAID keeps the array running through a hardware failure. A deleted file or ransomware is deleted or encrypted on every disk at once."],
  [17,"Why does a flash drive write more data than the computer asked it to?",["The computer sends everything twice","It cannot overwrite in place and must erase whole blocks, so garbage collection copies still-valid pages","Writes are always doubled for safety","The flash is slow"],1,"A page can only be written after its block is erased, and a block holds many pages. Moving valid pages out of a block before erasing it is extra writing."],
  [17,"What happens to write amplification as an SSD fills up, if writes are random?",["It falls","It rises, because blocks have more valid pages that must be copied","It stays exactly 1","It becomes zero"],1,"With less spare space, garbage collection finds blocks that are still mostly valid, so each erase costs more copying."],
  [17,"What does the TRIM command tell an SSD?",["To erase everything","Which blocks no longer hold data, so garbage collection need not copy them","To slow down","To mirror its data"],1,"Deleted file data otherwise looks valid to the drive. TRIM turns that space back into spare space, lowering write amplification."],
  [17,"What is the purpose of the commit record in a journaling file system?",["To compress the log","To make a logged update official in a single write, so the update is either replayed completely or ignored","To delete old files","To count free blocks"],1,"A crash before the commit record means no change happened; after it, recovery finishes the change. The disk never stays half-updated."]
].map(([mod, q, choices, answer, explain]) => ({ mod, q, choices, answer, explain }));
